--- 等待指定的时间。 任务将返回运行，直到任务完成等待。 在等待时间结束后它将返回成功。

------------ import ------------
local Behavior = import("Frame.AI.BT.Behavior")
------------ import ------------

------------ define ------------

------------ define ------------

---@class WaitAction
local WaitAction = Class("WaitAction", Behavior)

function WaitAction:__init(waitTime, isRealTime)
    Behavior.__init(self)
    self.btType = Behavior.BehaviorTreeType.Action
    
    self._waitTime   = waitTime
    self._isRealTime = isRealTime ~= nil and isRealTime ~= false
    
    self._startTime  = 0
end

function WaitAction:__delete()

end


function WaitAction:OnStart()
    self._startTime = 0
end

function WaitAction:Update(context)
    
    if self._startTime == 0 then
        --- 应该有个Utils  来获取 真实时间的
        self._startTime = os.time() 
    end

    if os.time() - self._startTime >= self._waitTime then
        return Behavior.TaskStatus.Success 
    end

    return Behavior.TaskStatus.Running
end


return WaitAction
 